import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.springframework.stereotype.Component;

@Component
public class OrderPricing {

    private static final double VAT_PERCENT = 23.0;

    /** Up to three digits, then an optional dot with one or two decimals. */
    private static final Pattern PERCENT = Pattern.compile("(\\d{1,3})(?:\\.(\\d{1,2}))?");

    public Money withVat(Money net) {
        double gross = net.minorUnits() * (100 + VAT_PERCENT) / 100;
        return new Money(Math.round(gross), net.currency());
    }

    /**
     * The discount on {@code total} for {@code percent} (text such as "12.5"),
     * rounded half up to a whole minor unit.
     */
    public Money discountOf(Money total, String percent) {
        long basisPoints = basisPoints(percent);
        // round(total * bp / 10000) half up == floor((2 * total * bp + 10000) / 20000), for total >= 0
        long doubled = Math.multiplyExact(Math.multiplyExact(total.minorUnits(), basisPoints), 2L);
        long discount = Math.floorDiv(Math.addExact(doubled, 10_000L), 20_000L);
        return new Money(discount, total.currency());
    }

    private static long basisPoints(String percent) {
        Matcher m = percent == null ? null : PERCENT.matcher(percent.trim());
        if (m == null || !m.matches()) {
            throw new ShopProblem("invalid-percent", "Not a percentage: " + percent);
        }
        long whole = Long.parseLong(m.group(1));
        String fraction = m.group(2) == null ? "00" : (m.group(2) + "0");
        long bp = whole * 100 + Long.parseLong(fraction);
        if (bp > 10_000) {
            throw new ShopProblem("invalid-percent", "A discount cannot exceed 100 percent: " + percent);
        }
        return bp;
    }
}
}

